// MT2009_PLUS_GAYA_V1 (cube helpers): a recipe's "gaya N" line - N Gaya (the item 95927, quest ygaya) from the
// inventory, checked before anything is taken and taken with the materials (a failed attempt takes it, as the Yang)
static const DWORD MT2009_GAYA_VNUM = 95927;
static bool Mt2009GayaCubeCheck(LPCHARACTER ch, const CUBE_DATA* cube)
{
	if (cube->gaya <= 0 || ch->CountSpecifyItem(MT2009_GAYA_VNUM) >= (ITEM_COUNT)cube->gaya)
		return true;
	ch->ChatPacket(CHAT_TYPE_INFO, "Masz za ma\263o Gaya (potrzeba %d).", cube->gaya);
	return false;
}
static void Mt2009GayaCubeTake(LPCHARACTER ch, const CUBE_DATA* cube)
{
	if (cube->gaya > 0)
		ch->RemoveSpecifyItem(MT2009_GAYA_VNUM, (ITEM_COUNT)cube->gaya);
}

